def chain_follows_chain(chain):
    tokens = list(chain)
    stack = []
    for token in tokens:
        if token == '(':
            stack.append(token)
        elif token == ')':
            if not stack:
                return "No valid chain"
            stack.pop()
    if not stack:
        return "No valid chain"
    return ','.join(stack)

# Example usage:
